type.example:
{
    ingredientPicker: true,
    confirmDialog: false,
    customIngredient: true
}

function.example:
const { openPanel, closePanel, isPanelOpen } = usePanels();

const handleOpenIngredients = () => {
    openPanel('ingredientPicker');
};

usage.panelExample:
// In a screen component
const { openPanel, closePanel, isPanelOpen, getPanelData } = usePanels();

const handleAddIngredient = () => {
    openPanel('ingredientPicker', { sectionId: 'proteins' });
};

const handleConfirm = () => {
    const data = getPanelData('ingredientPicker');
    console.log(data.sectionId); // 'proteins'
    closePanel('ingredientPicker');
};

hook.example:
export function MyComponent() {
    const { isDark, theme } = useTheme();

    return (
        <View style={{ backgroundColor: theme.background }}>
            <Text style={{ color: theme.text }}>
                {isDark ? 'Dark Mode' : 'Light Mode'}
            </Text>
        </View>
    );
}
